import pandas as pd

# Load available experiments
dfs = []
for i in [1, 4, 5, 6, 7, 8]:
    try:
        var_name = f"experiment_{i}_csv"
        if var_name in dir():
            dfs.append(pd.read_csv(eval(var_name)))
    except:
        pass

if not dfs:
    print("No files loaded.")
else:
    df = pd.concat(dfs, ignore_index=True)
    print("Columns:", df.columns.tolist())

    # Identify intervention columns automatically
    int_cols = [c for c in df.columns if any(k in c.lower() for k in ['ph', 'acid', 'iron', 'fert', 'dose', 'lvl'])]
    print("Intervention cols detected:", int_cols)

    # Print unique values for these columns
    for c in int_cols:
        print(f"{c} unique:", sorted(df[c].dropna().unique()))

    # Group and print mean yield
    if len(int_cols) >= 1:
        grp = df.groupby(int_cols, dropna=False)['CropYield'].agg(['mean', 'count']).reset_index()
        print("\nMean Yield by Intervention:")
        print(grp)
    else:
        print("CropYield stats:", df['CropYield'].describe())
